import {motions,puppetSVG,referenceLayer,motionPhase} from '../reference/puppet.js';
import {toSeconds,fromSeconds,frameTime} from '../animation/timing.js';
export function showPuppet(a){
 a.pause();a.properties.flush();a.stage.finishPath();let motion='walk',rotation=90,phase=0,playing=false,raf,drag,baking=false,cancelled=false;
 const d=a.dialog('Movement reference',`<p>A basic jointed human to trace. Rotate it, choose a cycle, then bake one transparent frame per project frame.</p><div class="puppet-layout"><div class="puppet-preview" role="img" aria-label="Rotatable human motion reference"></div><div class="puppet-controls"><div class="motion-choices">${motions.map(m=>`<button data-motion="${m}" class="${m==='walk'?'active':''}" aria-pressed="${m==='walk'}">${m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div><label>View rotation (degrees)<input data-puppet-angle type="range" min="0" max="360" value="90"><input data-puppet-angle-number type="number" min="0" max="360" value="90"></label><p class="subtle">0° front · 90° side · 180° back · drag the puppet to rotate</p><div class="dialog-grid"><label>Loop length<input data-puppet-length type="number" min="${1/a.doc.fps}" max="10" step="${1/a.doc.fps}" value="2"></label><label>Measurement<select data-puppet-unit><option value="seconds">Seconds</option><option value="frames">Frames</option><option value="bars">Bars</option></select></label></div><div class="dialog-grid"><label>Tempo (BPM)<input data-puppet-tempo type="number" min="20" max="300" value="${a.doc.playback?.bpm||120}"></label><label>Beats per bar<input data-puppet-beats type="number" min="1" max="16" value="${a.doc.playback?.beatsPerBar||4}"></label></div><label>Insert at<select data-puppet-start><option value="playhead">Playhead (${Number(a.time.toFixed(3))}s)</option><option value="zero">Composition start</option></select></label><label class="shadow-toggle"><input type="checkbox" data-puppet-export> Include reference in exports</label><button data-puppet-play>▶ Preview cycle</button><label>Cycle position<input data-puppet-scrub type="range" min="0" max="1" step=".001" value="0"></label></div></div><p class="subtle"><strong data-puppet-phase>Contact</strong> · Grounded support, impact compression, curved recovery, opposite arm swing and delayed hands/head. Cycles run in place: support feet travel back steadily as if on a moving floor. Pose references: <a href="https://www.adobe.com/creativecloud/animation/discover/animation-walk-cycle.html" target="_blank" rel="noopener">Adobe walk drawings</a> · <a href="https://www.animationmentor.com/blog/tutorial-animating-human-walk-cycle/" target="_blank" rel="noopener">Animation Mentor body mechanics</a>.</p><p data-puppet-summary role="status"></p><progress data-puppet-progress hidden max="1" value="0"></progress><div class="dialog-actions"><button data-puppet-cancel data-close>Cancel</button><button data-puppet-bake class="primary">Bake reference layer</button></div>`);d.classList.add('puppet-dialog');const preview=d.querySelector('.puppet-preview'),length=d.querySelector('[data-puppet-length]'),unit=d.querySelector('[data-puppet-unit]');let oldUnit='seconds';
 const clock=()=>({...a.doc,playback:{...a.doc.playback,bpm:Number(d.querySelector('[data-puppet-tempo]').value),beatsPerBar:Number(d.querySelector('[data-puppet-beats]').value)}});const duration=()=>Math.max(1/a.doc.fps,frameTime(a.doc,toSeconds(clock(),Number(length.value),unit.value))),start=()=>d.querySelector('[data-puppet-start]').value==='zero'?0:frameTime(a.doc,a.time);
 function draw(){preview.innerHTML=puppetSVG(motion,phase,rotation);d.querySelector("[data-puppet-phase]").textContent=motionPhase(motion,phase);d.querySelector('[data-puppet-scrub]').value=phase;d.querySelector('[data-puppet-summary]').textContent=`1 ${motion} cycle · ${duration()}s · ${Math.round(duration()*a.doc.fps)} PNG frames at ${a.doc.fps} fps → new locked reference layer. ${d.querySelector('[data-puppet-export]').checked?'Included in exports.':'Hidden from exports; visible on the canvas.'}`;}
 function stop(){playing=false;cancelAnimationFrame(raf);d.querySelector('[data-puppet-play]').textContent='▶ Preview cycle';}
 d.querySelector('[data-puppet-play]').onclick=()=>{if(playing)return stop();playing=true;const origin=performance.now()-phase*duration()*1000;d.querySelector('[data-puppet-play]').textContent='Ⅱ Pause preview';const tick=now=>{if(!playing)return;phase=((now-origin)/(duration()*1000))%1;draw();raf=requestAnimationFrame(tick);};raf=requestAnimationFrame(tick);};
 d.querySelectorAll('[data-motion]').forEach(b=>b.onclick=()=>{stop();motion=b.dataset.motion;phase=0;d.querySelectorAll('[data-motion]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',el===b);});draw();});
 for(const selector of ['[data-puppet-angle]','[data-puppet-angle-number]'])d.querySelector(selector).oninput=e=>{rotation=Math.max(0,Math.min(360,Number(e.target.value)||0));d.querySelector('[data-puppet-angle]').value=rotation;d.querySelector('[data-puppet-angle-number]').value=rotation;draw();};
 preview.onpointerdown=e=>{if(baking)return;e.preventDefault();stop();drag={id:e.pointerId,x:e.clientX,rotation};preview.setPointerCapture(e.pointerId);};preview.onpointermove=e=>{if(drag?.id!==e.pointerId)return;rotation=((drag.rotation+(e.clientX-drag.x)*.7)%360+360)%360;d.querySelector('[data-puppet-angle]').value=rotation;d.querySelector('[data-puppet-angle-number]').value=Math.round(rotation);draw();};preview.onpointerup=preview.onpointercancel=()=>drag=null;
 unit.onchange=()=>{const seconds=toSeconds(clock(),Number(length.value),oldUnit);length.value=fromSeconds(clock(),seconds,unit.value);length.min=unit.value==='frames'?1:1/a.doc.fps;length.max=unit.value==='frames'?a.doc.fps*10:unit.value==='bars'?fromSeconds(clock(),10,'bars'):10;length.step=unit.value==='frames'?1:unit.value==='bars'?.125:1/a.doc.fps;oldUnit=unit.value;draw();};d.querySelector('[data-puppet-tempo]').oninput=d.querySelector('[data-puppet-beats]').oninput=()=>{stop();draw();};length.oninput=()=>{stop();draw();};d.querySelector('[data-puppet-scrub]').oninput=e=>{stop();phase=Number(e.target.value);draw();};d.querySelector('[data-puppet-export]').onchange=draw;
 d.querySelector('[data-puppet-bake]').onclick=()=>a.safe(async()=>{const seconds=duration(),count=Math.round(seconds*a.doc.fps),offset=start();if(!Number.isFinite(seconds)||seconds<=0||seconds>10||count>600||offset+seconds>600)throw Error('Choose a cycle of up to 10 seconds and 600 frames.');stop();baking=true;cancelled=false;d.querySelectorAll('input,select,button').forEach(el=>el.disabled=!el.matches('[data-puppet-cancel]'));const progress=d.querySelector('[data-puppet-progress]');progress.hidden=false;const canvas=document.createElement('canvas');canvas.width=canvas.height=400;const ctx=canvas.getContext('2d'),image=new Image(),frames=[];try{for(let f=0;f<count;f++){if(cancelled)throw new DOMException('Cancelled','AbortError');image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(puppetSVG(motion,f/count,rotation,false));await image.decode();ctx.clearRect(0,0,400,400);ctx.drawImage(image,0,0);frames.push(canvas.toDataURL('image/png'));progress.value=(f+1)/count;if(f%8===0)await new Promise(requestAnimationFrame);}if(cancelled)return;const n=referenceLayer(a.doc,{motion,rotation,duration:seconds,start:offset,frames});n.exportIncluded=d.querySelector('[data-puppet-export]').checked;a.mutate('Bake movement reference',()=>{a.doc.duration=Math.max(a.doc.duration,offset+seconds);a.doc.layers.unshift(n);a.selected=[n.id];});d.close();a.toast(`${count} transparent PNG frames baked. Draw on a new layer above the reference.`);}catch(e){if(e.name!=='AbortError')throw e;}finally{baking=false;if(d.open)d.querySelectorAll('input,select,button').forEach(el=>el.disabled=false);}});
 d.addEventListener('close',()=>{cancelled=true;stop();},{once:true});draw();return d;
}
